def find_path(graph, start, goal):
  visited = set()

  def bfs(node):
    queue = [(node, [node])]
    while queue:
      (node, path) = queue.pop(0)  
      if node == goal:
        return path

      for neighbor in graph[node]:
        if neighbor not in visited:
          visited.add(neighbor)
          queue.append((neighbor, path + [neighbor]))

    return None

  if start in goal:
    return None

  return bfs(start)

