from collections import deque

def find_path(graph, start, goal):
    if start == goal:
        return [start]

    # To perform a Breadth-First Search (BFS)
    visited = set([start])
    queue = deque([start])

    while queue:
        curr = queue.popleft()

        for neighbor in graph[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

                if neighbor == goal:
                    path = [curr]
                    while path[-1] != start  :
                        pre = graph[path[-1]].index(neighbor)
                        path.append(path.pop(pre))
                    return path + [neighbor]
    return None
```

