def find_path(graph, start, goal):
    explored = []
    queue = [[start]]
    
    if start == goal:
        return [goal]

    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node not in explored:
            neighbours = graph[node]
            if goal in neighbours:
                path += [goal]
                return path
            else:
                for neighbour in neighbours:
                    new_path = list(path)
                    new_path += [neighbour]
                    queue.append(new_path)
                explored.append(node)
            
    return None
